package dev.veltraph.client.capture.tool;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class SelectedToolCaptureScopeTest {
 private final Object p=new Object(),w=new Object(),c=new Object();
 private SelectedToolCaptureScope.Frame frame(Object player,Object world,Object connection,Object account,int slot,boolean gui,boolean manual){return new SelectedToolCaptureScope.Frame(player,world,connection,account,slot,"minecraft:diamond_axe",gui,manual);}
 @Test void explicitOffStartSampleFinishLifecycle(){var s=new SelectedToolCaptureScope();var f=frame(p,w,c,"in-memory-account",0,true,true);assertFalse(s.current(f));assertTrue(s.start(f));assertTrue(s.current(f));assertFalse(s.start(f));s.end();assertFalse(s.active());assertFalse(s.current(f));assertTrue(s.start(f));}
 @Test void worldPlayerConnectionAccountSlotGuiAndMacroBoundariesDenied(){var s=new SelectedToolCaptureScope();assertTrue(s.start(frame(p,w,c,"account",0,true,true)));assertFalse(s.current(frame(new Object(),w,c,"account",0,true,true)));assertFalse(s.current(frame(p,new Object(),c,"account",0,true,true)));assertFalse(s.current(frame(p,w,new Object(),"account",0,true,true)));assertFalse(s.current(frame(p,w,c,"other-account",0,true,true)));assertFalse(s.current(frame(p,w,c,"account",1,true,true)));assertFalse(s.current(frame(p,w,c,"account",0,false,true)));assertFalse(s.current(frame(p,w,c,"account",0,true,false)));}
 @Test void missingNativeScopeAndNoToolCannotStart(){var s=new SelectedToolCaptureScope();assertFalse(s.start(frame(null,w,c,"account",0,true,true)));assertFalse(s.start(new SelectedToolCaptureScope.Frame(p,w,c,"account",0,"minecraft:air",true,true)));assertFalse(s.start(frame(p,w,c,null,0,true,true)));}
 @Test void terminalWriterRetiresScopeWipesSaltAndAllowsNewStart(){var scope=new SelectedToolCaptureScope();var f=frame(p,w,c,"account",0,true,true);assertTrue(scope.start(f));byte[] salt=new byte[32];java.util.Arrays.fill(salt,(byte)7);scope.writerEnded(salt);assertFalse(scope.active());assertArrayEquals(new byte[32],salt);assertTrue(scope.start(f));}
 @Test void invalidCollectedFrameCannotBeRescuedByRestoredFinalFrame(){var scope=new SelectedToolCaptureScope();var admitted=frame(p,w,c,"account",0,true,true);assertTrue(scope.start(admitted));assertTrue(scope.current(admitted));var collected=frame(p,w,c,"account",1,true,true);boolean heldFrameCurrent=scope.current(collected);assertTrue(scope.current(admitted));assertFalse(heldFrameCurrent,"Already observed foreign slot remains denied even when final context is restored");}
}
